// Package scan recognises a gym machine in a photo. It sends the photo and Kinzo's machine list
// to a Claude vision model, which picks the machines it could be and the exercise variation it
// most likely shows.
//
// The machine list (machines.json) is generated by tools/catalogue/build_catalogue.py from
// the same data as the app's catalogue, so the IDs it returns are ones the phone already has.
package scan

import (
	"context"
	_ "embed"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"strconv"
	"strings"

	"github.com/anthropics/anthropic-sdk-go"
	"github.com/anthropics/anthropic-sdk-go/option"
)

//go:embed machines.json
var machinesJSON []byte

// DefaultModel is cheap enough to make scanning free with a daily cap: about a tenth of a
// penny a scan. Switch with KINZO_SCAN_MODEL if a test set shows it confusing machines.
const DefaultModel = "claude-haiku-5-5"

// MaxMatches is how many machines a result offers, best first.
const MaxMatches = 3

// Catalogue is the machine list the model chooses from.
type Catalogue struct {
	Version  int       `json:"version"`
	Machines []Machine `json:"machines"`
}

type Machine struct {
	ID          string     `json:"id"`
	Name        string     `json:"name"`
	Aliases     []string   `json:"aliases"`
	Description string     `json:"description"`
	Exercises   []Exercise `json:"exercises"`
}

type Exercise struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

// LoadCatalogue reads the machine list built into the binary.
func LoadCatalogue() (Catalogue, error) {
	var c Catalogue
	if err := json.Unmarshal(machinesJSON, &c); err != nil {
		return Catalogue{}, fmt.Errorf("read machines.json: %w", err)
	}
	if len(c.Machines) == 0 {
		return Catalogue{}, errors.New("machines.json lists no machines")
	}
	return c, nil
}

// Confidence is how sure the model is of a match.
type Confidence string

const (
	High   Confidence = "high"
	Medium Confidence = "medium"
	Low    Confidence = "low"
)

// Match is one machine the photo could show.
type Match struct {
	MachineID  string     `json:"machine_id"`
	Confidence Confidence `json:"confidence"`
}

// Result is what a scan found. Matches is empty when the photo shows no machine Kinzo knows;
// Description then says what the model saw, so the app can offer to save it as the user's own.
type Result struct {
	Matches []Match `json:"matches"`
	// ExerciseID is the variation the photo most likely shows (an incline press rather than a
	// flat one, say), or empty when it can't tell. It always belongs to the first match.
	ExerciseID  string `json:"exercise_id,omitempty"`
	Description string `json:"description"`
}

// ErrUnreadable means the model couldn't work with the photo, for example because it refused.
var ErrUnreadable = errors.New("the photo couldn't be read")

// Recogniser matches photos against the catalogue.
type Recogniser struct {
	client    anthropic.Client
	model     string
	catalogue Catalogue
	// The machine list as the model reads it. Fixed, so it caches between scans.
	system string
}

// NewRecogniser makes a recogniser that calls the Claude API with apiKey. Extra options are for
// tests, which point it at a fake server.
func NewRecogniser(apiKey, model string, catalogue Catalogue, opts ...option.RequestOption) *Recogniser {
	if model == "" {
		model = DefaultModel
	}
	opts = append([]option.RequestOption{option.WithAPIKey(apiKey)}, opts...)
	return &Recogniser{
		client:    anthropic.NewClient(opts...),
		model:     model,
		catalogue: catalogue,
		system:    systemPrompt(catalogue),
	}
}

// Machine codes ("M3") and exercise codes ("M3.2") keep the prompt and the answer short; they
// map back to catalogue IDs here, so the model never has to copy a UUID.
func machineCode(i int) string     { return "M" + strconv.Itoa(i+1) }
func exerciseCode(i, j int) string { return machineCode(i) + "." + strconv.Itoa(j+1) }
func parseCode(code string) []string {
	return strings.Split(strings.TrimPrefix(strings.TrimSpace(code), "M"), ".")
}

func systemPrompt(c Catalogue) string {
	var b strings.Builder
	b.WriteString(`You identify gym equipment in photos for a workout-logging app. The person is standing at a machine and wants to log the exercise they're about to do, but doesn't know what the machine is called.

Pick the machines from the list below that the photo could show, best first, at most three. Only list a machine if it is a real possibility. If the photo shows equipment that isn't on the list, or no gym equipment at all, list none.

Then pick the exercise variation the photo most likely shows, from the first machine's exercises. Use what you can see: the angle of the seat or back pad (flat, incline, decline), the handle positions (wide, neutral, single-arm), plate horns versus a weight stack, and any placard or label on the machine. If you can't tell which variation it is, leave the exercise empty.

Finally, describe the equipment in one short sentence a gym-goer would understand, such as "A plate-loaded incline chest press with independent arms." If it isn't on the list, this description is all the person gets, so make it specific.

Confidence: "high" when you're sure, "medium" when it's likely but a similar machine is possible, "low" when it's a guess.

Machines (code | name | other names | what it looks like), each followed by its exercises:
`)
	for i, m := range c.Machines {
		fmt.Fprintf(&b, "\n%s | %s | %s | %s\n", machineCode(i), m.Name, strings.Join(m.Aliases, ", "), m.Description)
		for j, e := range m.Exercises {
			fmt.Fprintf(&b, "  %s %s\n", exerciseCode(i, j), e.Name)
		}
	}
	return b.String()
}

// answer is the shape the model is asked to reply in.
type answer struct {
	Machines []struct {
		Code       string `json:"code"`
		Confidence string `json:"confidence"`
	} `json:"machines"`
	Exercise    string `json:"exercise"`
	Description string `json:"description"`
}

var answerSchema = map[string]any{
	"type": "object",
	"properties": map[string]any{
		"machines": map[string]any{
			"type": "array",
			"items": map[string]any{
				"type": "object",
				"properties": map[string]any{
					"code":       map[string]any{"type": "string", "description": `A machine code such as "M3".`},
					"confidence": map[string]any{"type": "string", "enum": []string{"high", "medium", "low"}},
				},
				"required":             []string{"code", "confidence"},
				"additionalProperties": false,
			},
		},
		"exercise": map[string]any{
			"type":        "string",
			"description": `An exercise code from the first machine, such as "M3.2", or "" when you can't tell.`,
		},
		"description": map[string]any{"type": "string"},
	},
	"required":             []string{"machines", "exercise", "description"},
	"additionalProperties": false,
}

// Recognise asks the model which machine the photo shows. mediaType is "image/jpeg" or
// "image/png".
func (r *Recogniser) Recognise(ctx context.Context, image []byte, mediaType string) (Result, error) {
	msg, err := r.client.Messages.New(ctx, anthropic.MessageNewParams{
		Model:     r.model,
		MaxTokens: 4000,
		System: []anthropic.TextBlockParam{{
			Text:         r.system,
			CacheControl: anthropic.NewCacheControlEphemeralParam(),
		}},
		Messages: []anthropic.MessageParam{
			anthropic.NewUserMessage(
				anthropic.NewImageBlockBase64(mediaType, base64.StdEncoding.EncodeToString(image)),
				anthropic.NewTextBlock("Which machine is this?"),
			),
		},
		OutputConfig: anthropic.OutputConfigParam{
			Effort: anthropic.OutputConfigEffortLow,
			Format: anthropic.JSONOutputFormatParam{Schema: answerSchema},
		},
	})
	if err != nil {
		return Result{}, fmt.Errorf("ask the model: %w", err)
	}
	if msg.StopReason == anthropic.StopReasonRefusal {
		return Result{}, ErrUnreadable
	}
	var text strings.Builder
	for _, block := range msg.Content {
		if t, ok := block.AsAny().(anthropic.TextBlock); ok {
			text.WriteString(t.Text)
		}
	}
	var a answer
	if err := json.Unmarshal([]byte(text.String()), &a); err != nil {
		return Result{}, fmt.Errorf("%w: unexpected answer: %v", ErrUnreadable, err)
	}
	return r.resolve(a), nil
}

// resolve turns the model's codes into catalogue IDs, dropping any code that doesn't exist.
func (r *Recogniser) resolve(a answer) Result {
	res := Result{Matches: []Match{}, Description: strings.TrimSpace(a.Description)}
	seen := map[int]bool{}
	first := -1
	for _, m := range a.Machines {
		parts := parseCode(m.Code)
		i, err := strconv.Atoi(parts[0])
		if err != nil || len(parts) != 1 || i < 1 || i > len(r.catalogue.Machines) || seen[i] {
			continue
		}
		seen[i] = true
		if first < 0 {
			first = i - 1
		}
		confidence := Confidence(m.Confidence)
		if confidence != High && confidence != Medium {
			confidence = Low
		}
		res.Matches = append(res.Matches, Match{MachineID: r.catalogue.Machines[i-1].ID, Confidence: confidence})
		if len(res.Matches) == MaxMatches {
			break
		}
	}
	if first >= 0 && a.Exercise != "" {
		parts := parseCode(a.Exercise)
		if len(parts) == 2 {
			i, errI := strconv.Atoi(parts[0])
			j, errJ := strconv.Atoi(parts[1])
			exercises := r.catalogue.Machines[first].Exercises
			if errI == nil && errJ == nil && i-1 == first && j >= 1 && j <= len(exercises) {
				res.ExerciseID = exercises[j-1].ID
			}
		}
	}
	return res
}
